// Compile the LOOM bundle JSON Schema into TypeScript types. Called by `loom contracts export`; prints to stdout.
import { readFileSync } from "node:fs";
import { compile } from "json-schema-to-typescript";

const bundlePath = process.argv[2];
if (!bundlePath) {
  console.error("usage: node generate.mjs <loom.bundle.schema.json>");
  process.exit(2);
}
const schema = JSON.parse(readFileSync(bundlePath, "utf-8"));

const ts = await compile(schema, "LoomContracts", {
  bannerComment:
    "/* eslint-disable */\n/**\n * GENERATED by `loom contracts export` from loom/core/contracts (Pydantic v2).\n * Do not edit by hand.\n */",
  additionalProperties: false,
  unreachableDefinitions: true,
  declareExternallyReferenced: true,
  strictIndexSignatures: true,
  format: true,
  style: { printWidth: 120, singleQuote: false },
});
process.stdout.write(ts);
